async function changePane(value){pane.value=value;if(value==='issues'){loading.value=true;try{issues.value=(await api('issues')).issues}catch(e){error.value=e.message}finally{loading.value=false}}else await load()}
function newProject(old){usingExisting.value=!!old;Object.assign(creation,{kind:old?.kind||(old&&['team','player'].includes(old.preload?.type)?'honor':'progression'),title:old?.title||'',preload:old?{...old.preload}:{type:'platform',targetId:''},importTemplateIds:old?(old.importTemplateIds||[old.id]):[]});targets.value=old?.preload?.targetId?[{id:old.preload.targetId,name:old.preload.targetName||old.preload.targetId}]:[];createOpen.value=true}
function changeKind(){if(creation.kind==='progression'&&!['platform','tournament'].includes(creation.preload.type))creation.preload={type:'platform',targetId:''}}
function resetTargets(){creation.preload.targetId='';targets.value=[];targetCursor.value=''}
async function searchTargets(keyword='',more=false){if(creation.preload.type==='platform')return;targetsLoading.value=true;targetKeyword.value=keyword;try{const r=await playerCardTemplateRequest('listPlayerCardPreloadTargets',{type:creation.preload.type,keyword,cursor:more?targetCursor.value:''});if(!r.success)throw new Error(r.error);targets.value=more?[...targets.value,...r.targets]:r.targets;targetCursor.value=r.nextCursor||''}catch(e){ElMessage.error(e.message)}finally{targetsLoading.value=false}}
function moreTargets(){return searchTargets(targetKeyword.value,true)}
async function create(){busy.value=true;try{const r=await api('create',JSON.parse(JSON.stringify(creation)));project.value=r.set;variant.value=project.value.kind==='progression'?'bronze':'single';step.value=1;createOpen.value=false;clearMaterialFiles()}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function openProject(id){busy.value=true;try{project.value=(await api('get',{setId:id})).set;variant.value=project.value.kind==='progression'?'bronze':'single';step.value=Object.values(project.value.members).every(x=>x.backgroundFileId&&x.maskFileId)?2:1;clearMaterialFiles()}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function reloadProject(){project.value=(await api('get',{setId:project.value._id})).set}
async function validateFile(file){if(!file||file.size>2*1024*1024||!(/\.png$/i.test(file.name)))throw new Error('请选择小于2MB的PNG');const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);if(bytes[0]!==137||bytes[1]!==80||bytes[2]!==78||bytes[3]!==71)throw new Error('文件不是PNG');if(buffer.byteLength<24)throw new Error('PNG文件不完整');const view=new DataView(buffer);if(view.getUint32(16)!==300||view.getUint32(20)!==430)throw new Error('图片尺寸须为300×430');return file}
function clearMaterialFiles(key){for(const name of key?[key]:Object.keys(files)){const selected=files[name];if(!selected)continue;for(const layer of ['background','mask'])if(selected[layer+'Preview'])URL.revokeObjectURL(selected[layer+'Preview']);delete files[name]}}
function selectMaterial(key,layer,file){const selected=files[key]||={};if(selected[layer+'Preview'])URL.revokeObjectURL(selected[layer+'Preview']);selected[layer]=file;selected[layer+'Preview']=URL.createObjectURL(file);materialError.value='';uploadProgress.value=''}
async function chooseFile(event,key,layer){const input=event.target,file=input.files?.[0],setId=project.value?._id;try{if(file){await validateFile(file);if(project.value?._id===setId)selectMaterial(key,layer,file)}}catch(e){ElMessage.error(e.message)}finally{input.value=''}}
async function chooseBatch(event){const input=event.target,selectedFiles=[...(input.files||[])],setId=project.value?._id;try{for(const file of selectedFiles){await validateFile(file);if(project.value?._id!==setId)return;const mask=/遮罩|mask/i.test(file.name),key=mask&&sharedMask.value?'common':project.value.kind==='honor'?'single':/铜|bronze/i.test(file.name)?'bronze':/银|silver/i.test(file.name)?'silver':/金|gold/i.test(file.name)?'gold':'';if(!key)throw new Error('无法识别 '+file.name+'，请使用单项选择');selectMaterial(key,mask?'mask':'background',file)}}catch(e){ElMessage.error(e.message)}finally{input.value=''}}
async function upload(file,layer){const token=crypto.randomUUID();uploadProgress.value='正在上传 '+file.name;const r=await uploadLargeFileViaCloud(`player-card-template-uploads/${token}/${layer}/asset.png`,file,{chunkSize:16*1024,fallbackChunkSize:8*1024,onProgress:(done,total)=>{uploadProgress.value=`正在上传 ${file.name}：${done}/${total}`}});return r.fileId}
async function saveMaterials(next){if(busy.value)return false;busy.value=true;materialError.value='';try{const common=sharedMask.value&&files.common?.mask?await upload(files.common.mask,'mask'):'';for(const key of variantKeys.value){const chosen=files[key]||{},member=project.value.members[key];if(!chosen.background&&!chosen.mask&&!common)continue;const input={key,revision:member.revision};if(chosen.background)input.backgroundFileId=await upload(chosen.background,'background');if(common)input.maskFileId=common;else if(chosen.mask)input.maskFileId=await upload(chosen.mask,'mask');uploadProgress.value='正在保存'+tierLabel(key)+'素材';const r=await api('materials',{setId:project.value._id,variants:[input]});project.value=r.set;clearMaterialFiles(key)}clearMaterialFiles('common');uploadProgress.value='';if(next){if(!Object.values(project.value.members).every(x=>x.backgroundFileId&&x.maskFileId))throw new Error('请补齐各档背景和遮罩');step.value=2}ElMessage.success('素材已保存');return true}catch(e){uploadProgress.value='';materialError.value=e.message+(hasPendingMaterials.value?'；未保存的选择已保留，可重试。':'');ElMessage.error(e.message);await reloadProject().catch(()=>{});return false}finally{busy.value=false}}
async function saveLayout(){busy.value=true;try{if(editor.value?.isDirty()){const ok=await editor.value.saveChanges();if(!ok)return false}await reloadProject();return true}catch(e){ElMessage.error(e.message);return false}finally{busy.value=false}}
async function copyCurrentLayout(){if(busy.value||!editor.value||project.value.kind!=='progression')return;const sourceKey=variant.value,others=variantKeys.value.filter(key=>key!==sourceKey).map(tierLabel).join('、');try{await ElMessageBox.confirm(`将${tierLabel(sourceKey)}的文字样式、位置、人物构图和徽标排版覆盖到${others}。各档背景和遮罩保留。`,'同步排版',{confirmButtonText:'确认同步',cancelButtonText:'取消',type:'warning'})}catch{return}if(!await saveLayout())return;busy.value=true;try{const form=editor.value.formData();const result=await api('copyLayout',{setId:project.value._id,sourceKey,revision:form.revision});project.value=result.set;ElMessage.success('已同步到'+others)}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
